SELECT * FROM cage_shelf_cell_snapshot
WHERE room_id = #{roomId} AND shelve_id = #{shelveId}
  AND scan_batch_id = (
      SELECT scan_batch_id FROM cage_shelf_cell_snapshot
      WHERE room_id = #{roomId} AND shelve_id = #{shelveId}
      ORDER BY scanned_at DESC LIMIT 1
  )
ORDER BY position_y, position_x

SELECT * FROM cage_shelf_cell_snapshot
WHERE scan_batch_id = #{scanBatchId} AND shelve_id = #{shelveId}
ORDER BY position_y, position_x
